#!/bin/sh
# Regenerates src/Puntjes.Sdk/Generated from spec/api.json with the pinned images. Never edit src/Puntjes.Sdk/Generated by hand.
set -eu
root=$(cd "$(dirname "$0")/.." && pwd)
kiota="mcr.microsoft.com/openapi/kiota@sha256:ec6d326a8f98a067106729903928535906044aa1a42dbd1825c384080da76b13"
sdk="mcr.microsoft.com/dotnet/sdk@sha256:548d93f8a18a1acbe6cc127bc4f47281430d34a9e35c18afa80a8d6741c2adc3"
out=src/Puntjes.Sdk/Generated
rm -rf "${root:?}/$out"
docker run --rm -u "$(id -u):$(id -g)" -e KIOTA_OFFLINE_ENABLED=true -v "$root:/w" "$kiota" generate \
  -l CSharp -d /w/spec/api.json -o "/w/$out" -n Puntjes.Sdk.Generated -c PuntjesClient \
  --serializer Microsoft.Kiota.Serialization.Json.JsonSerializationWriterFactory \
  --serializer Microsoft.Kiota.Serialization.Text.TextSerializationWriterFactory \
  --deserializer Microsoft.Kiota.Serialization.Json.JsonParseNodeFactory \
  --deserializer Microsoft.Kiota.Serialization.Text.TextParseNodeFactory \
  --exclude-backward-compatible --clean-output --log-level Warning
docker run --rm -u "$(id -u):$(id -g)" -e HOME=/tmp -e DOTNET_CLI_HOME=/tmp -e DOTNET_NOLOGO=1 \
  -e DOTNET_CLI_TELEMETRY_OPTOUT=1 -v "$root:/w" -w /w "$sdk" \
  dotnet run --project tools/Puntjes.Tools -f net10.0 -- codegen spec/api.json "$out"
